[4021] = { en = "Counterattack!", tier = 1,
  t = "Tegenaanval!",
  d = "De Horde prijst je succes tegen de Kolkar. Maar de Kolkar zelf zijn razend geworden. Ik heb berichten dat een groep Kolkar uit hun thuis in Desolace naar de Barrens is gekomen. Ze willen wraak. Volgens mijn laatste bericht trekken ze nu al op tegen deze bunkers, vanuit het westen!$B$BVecht tegen de Kolkar-indringers en maak een einde aan hun dreiging in de Barrens. Dood ze tot hun leider, Warlord Krom'zar, verschijnt. Versla hem en breng me een stuk van zijn banier als bewijs.$B$BWe rekenen op je, $N.",
  o = "Breng een Piece of Krom'zar's Banner naar Regthar Deathgate, ten westen van de Crossroads.",
  p = "Heb je de banier?",
  c = "Het is je gelukt! Je hebt de Kolkar verslagen!$B$BIk zorg ervoor dat Thrall hoort wat je hier gedaan hebt, $N.$B$BSta rechtop. Je maakt jezelf en de Horde trots.",
  g = { {"Tegenaanval", "counterattack"}, {"prijst", "praises (prijzen)"}, {"razend", "furious, maddened"}, {"wraak", "revenge"}, {"trekken ... op", "march, advance (optrekken)"}, {"indringers", "invaders (indringer)"}, {"dreiging", "threat"}, {"verschijnt", "appears (verschijnen)"}, {"Versla", "defeat (verslaan)"}, {"banier", "banner"}, {"bewijs", "proof"}, {"rekenen op", "count on"} },
},

[4921] = { en = "Lost in Battle", tier = 1,
  t = "Verloren in de strijd",
  d = "We vochten in een klein kamp van de tauren. Toen raakten we elkaar kwijt. Ze hield in haar eentje drie Bristlebacks tegen. Maar het werden er te veel voor ons. Ik lokte er een paar weg. Toen zag ik hoe nieuwe vijanden haar overweldigden. In mijn woede draaide ik me om naar mijn vijanden. Maar ze waren met zo veel dat ze me makkelijk neersloegen.$B$BIk werd wakker en een tauren-druïde verzorgde mijn wonden. Hij had me gevonden op de Gold Road, toen ik viel.$B$BAlsjeblieft, $c, zoek een teken van mijn vrouw.",
  o = "Zoek de vrouw van Mankrik en ga dan terug naar hem in de Crossroads.",
  p = "Heb je al een teken van haar gevonden? De pijn in mijn borst zegt me dat het ergste is gebeurd. Maar ik hoop dat je haar veilig en gezond vindt.",
  c = "Ik begrijp het. Dank je, $c.",
  o1 = "Vind de vrouw van Mankrik",
  g = { {"raakten ... kwijt", "lost (kwijtraken)"}, {"in haar eentje", "by herself"}, {"hield ... tegen", "held off (tegenhouden)"}, {"lokte", "lured (lokken)"}, {"overweldigden", "overwhelmed (overweldigen)"}, {"woede", "rage, anger"}, {"neersloegen", "knocked down (neerslaan)"}, {"verzorgde", "tended (verzorgen)"}, {"wonden", "wounds (wond)"}, {"teken", "sign"}, {"borst", "chest"}, {"het ergste", "the worst"} },
},

[5042] = { en = "Agamaggan's Strength", tier = 1,
  t = "De kracht van Agamaggan",
  p = "Ik heb 4 bloedscherven nodig als je de kracht van Agamaggan wilt, $r.$B$BJe vijanden zullen bang wegkruipen voor je kracht als je deze zegen krijgt. <snuift>$B$BDe grootste krijgers van de Razormane zijn vol van zulke kracht!",
  c = "Kon Mangletooth maar vrij zijn om te zien hoe je de verraders vernietigt! <snuift>$B$BIk dank je dat je meer Bristlebacks hebt vernietigd om deze scherven te verzamelen. Ga daar alsjeblieft mee door, dan blijf ik je helpen. <snuift>",
  g = { {"bloedscherven", "blood shards (bloedscherf)"}, {"wegkruipen", "cower, creep away"}, {"zegen", "blessing"}, {"<snuift>", "<snorts> (snuiven)"}, {"Kon ... maar", "if only ... could"}, {"verraders", "traitors (verrader)"}, {"vernietigt", "destroy (vernietigen)"}, {"scherven", "shards (scherf)"}, {"verzamelen", "collect, gather"} },
},

[5043] = { en = "Agamaggan's Agility", tier = 1,
  t = "De behendigheid van Agamaggan",
  p = "Men zegt dat de beste verkenners van mijn stam niemand gelijk hebben in hun precisie. En geen schurk <snuift> is zo snel als zij in de strijd.$B$BBreng me 4 bloedscherven en ik maak je nog behendiger dan elk geboren quilboar.",
  c = "Moge je doel altijd raak zijn, en moge je wapen altijd goed treffen, $r.$B$BDe geest van Agamaggan is met je. Kom <snuift> terug naar me als je wilt. Mangletooth zal je opnieuw zegenen als de grote zwijnengod mij waardig vindt. <snuift>",
  g = { {"behendigheid", "agility"}, {"verkenners", "scouts (verkenner)"}, {"stam", "tribe"}, {"niemand gelijk hebben", "have no equal"}, {"precisie", "accuracy"}, {"schurk", "rogue"}, {"behendiger", "more agile (behendig)"}, {"raak", "on target"}, {"treffen", "hit, strike"}, {"zegenen", "bless"}, {"zwijnengod", "boar god"}, {"waardig", "worthy"} },
},

[5044] = { en = "Wisdom of Agamaggan", tier = 1,
  t = "De wijsheid van Agamaggan",
  p = "De sjamanen en geomancers van de quilboar-stammen <snuift> roepen de kracht van Agamaggan aan. Die helpt hen in de strijd en in hun rituelen, $r.$B$BWil jij ook de extra kracht van de zegen van Agamaggan voor je spreuken? Breng me dan 4 bloedscherven en Mangletooth zal je helpen. <snuift>",
  c = "Je vijanden moeten nu nog banger voor je zijn, $r. <snuift>$B$BVertel Mangletooth verhalen over je sluwheid in de strijd als we elkaar weer zien, in dit leven of in het volgende. <snuift>",
  g = { {"wijsheid", "wisdom"}, {"sjamanen", "shamans (sjamaan)"}, {"roepen ... aan", "call upon (aanroepen)"}, {"rituelen", "rituals (ritueel)"}, {"spreuken", "spells (spreuk)"}, {"banger", "more afraid (bang)"}, {"sluwheid", "cunning"}, {"het volgende", "the next one"} },
},

[5045] = { en = "Rising Spirit", tier = 1,
  t = "Opstijgende geest",
  p = "Alle soorten krijgers <snuift> hebben een sterke geest nodig. Die drijft je tot grotere daden als alle hoop verloren is. Dat weten de <snuift> Razormane ook. We zijn een spirituele stam. We zijn trotser op onze band met Agamaggan dan op onze kracht <snuift> in de strijd.$B$BBreng me 4 bloedscherven en ik zegen je geest voor de strijd. <snuift>",
  c = "Onze grootste krijgers en onze grootste <snuift> sjamanen zouden jaloers zijn op je wilskracht, $r.$B$BVersla meer Bristlebacks en weet dat ze je niet kunnen tegenhouden! <snuift>",
  g = { {"Opstijgende", "rising (opstijgen)"}, {"drijft", "drives (drijven)"}, {"daden", "deeds (daad)"}, {"hoop", "hope"}, {"spirituele", "spiritual"}, {"trotser", "prouder (trots)"}, {"band", "bond, connection"}, {"jaloers", "jealous, envious"}, {"wilskracht", "willpower"}, {"tegenhouden", "stop, hold back"} },
