[5046] = { en = "Razorhide", tier = 1,
  t = "Razorhide",
  p = "Iedereen die <snuift> ten strijde trekt, heeft bescherming nodig. Hun botten moeten sterk zijn. Hun huid taai. <snuift> Mijn stam weet dat ook. Onze stekels en huid beschermen ons van nature. Maar daarnaast <snuift> vragen we Agamaggan vaak om ons tegen kwaad te beschermen voordat we ten oorlog trekken.$B$BBreng me 4 bloedscherven <snuift> en ik geef je dezelfde bescherming.",
  c = "Trek ten oorlog, $r.",
