},

[6382] = { en = "The Ashenvale Hunt", tier = 1,
  t = "De jacht in Ashenvale",
  d = "Je kracht maakt indruk op me, $c. Je bent bereid om de jacht te omarmen. Daardoor geloof ik dat je verder kunt gaan naar groter wild... en grotere uitdagingen.$B$BDe bossen van Ashenvale zijn een groot, wild gebied. De Horde wil daar haar eigen wil opleggen, zowel politiek als spiritueel. Wil je jezelf bewijzen in een onbekend land? Zoek dan de hulp van Senani Thunderheart in Splintertree Post. Die buitenpost ligt recht naar het noorden van het pad dat uit de Barrens komt.",
  o = "Praat met Senani Thunderheart in Splintertree Post, Ashenvale.",
  c = "Welkom aan de nieuwe grens, $N. Ashenvale is een land vol kansen. Een jonge $C zoals jij kan hier eindeloos veel kansen vinden om te laten zien wat je waard bent. Kijk rond in de buitenpost hier. En reis zeker naar de Zoram Strand, want de Horde heeft daar ook een buitenpost.$B$BJe bent hier, dus je wilt meer leren over de jacht. Luister goed, dan vertel ik je graag wat je moet weten.",
  g = { {"maakt indruk", "impresses (indruk maken)"}, {"bereid", "willing"}, {"omarmen", "embrace"}, {"wild", "game (animals); wild"}, {"uitdagingen", "challenges (uitdaging)"}, {"opleggen", "impose"}, {"zowel ... als", "both ... and"}, {"politiek", "politically"}, {"bewijzen", "prove"}, {"buitenpost", "outpost"}, {"grens", "frontier, border"}, {"kansen", "chances, opportunities (kans)"}, {"eindeloos", "endless(ly)"}, {"wat je waard bent", "what you are worth, your mettle"} },
},

[878] = { en = "Tribes at War", tier = 2,
  t = "Stammen in oorlog",
  d = "Je moet mijn vijanden aanvallen. <snuift> Je moet Mangletooth en de Razormane helpen door de Bristlebacks te verzwakken. Beide stammen zijn erg spiritueel. Ze zijn verbonden met de aarde en haar kracht. <snuift> Die geeft ons kracht in alles... vooral in oorlog.$B$BWil je weten wie Thork <snuift> en de Horde echt zoveel leed bezorgt? Help dan Mangletooth! Val de spirituele leiders van de Bristlebacks in het noorden aan. Verzwak ze, zodat de Razormanes ze kunnen verslaan en over de Barrens kunnen heersen.",
  o = "Dood 6 Bristleback Water Seekers, 12 Bristleback Thornweavers en 12 Bristleback Geomancers en ga terug naar Mangletooth in Camp Taurajo in de Barrens.",
  p = "Meer informatie <snuift> voor de Horde als je de wijzen van de Bristlebacks hebt gedood, $r. <snuift> Geen moment eerder! Mangletooth is geen dwaas.",
  c = "Ja, ja... vol vreugde, want eindelijk <snuift> kennen de Bristlebacks de pijn van mijn stam, $r. Zo zou ik me moeten voelen. Maar dat <snuift> is niet zo.$B$BJij helpt je volk en zij eren je. Mangletooth helpt zijn volk, en wat doen zij? Ze keren hem de rug toe. Ze vergeten hem en laten hem wegrotten in een kooi!$B$BIk help ze zelfs nu ik achter tralies zit, en ze sturen niemand om me te redden!",
  g = { {"verzwakken", "weaken"}, {"verbonden", "connected, tied (verbinden)"}, {"leed bezorgt", "causes suffering (leed bezorgen)"}, {"Verzwak", "weaken (verzwakken)"}, {"heersen", "rule"}, {"wijzen", "wise ones (wijze)"}, {"dwaas", "fool"}, {"vreugde", "joy"}, {"eren", "honor (eren)"}, {"keren ... de rug toe", "turn their backs on (de rug toekeren)"}, {"wegrotten", "rot away"}, {"kooi", "cage"}, {"tralies", "bars"} },
},

[5052] = { en = "Blood Shards of Agamaggan", tier = 2,
  t = "Bloedscherven van Agamaggan",
  d = "Naast de doornen had het bloed <snuift> ook invloed op andere delen van de aarde: bloedrode stenen, gemengd met andere mineralen. De Bristlebacks graven deze scherven op. Ze dragen ze als totems <snuift> voor kracht in de strijd, en als totems voor hun magie. <snuift>$B$BIk ken de geheimen van die magie.$B$BBreng Mangletooth één van deze bloedscherven om te laten zien dat je het begrijpt. Breng Mangletooth veel scherven, dan zegent hij je met quilboar-magie: de magie van Agamaggan! <snuift>",
  o = "Breng een Blood Shard naar Mangletooth in Camp Taurajo in de Barrens.$B$BVerzamel meer Blood Shards als je wilt dat hij je zegent met de kracht van Agamaggan.",
  p = "Onze stammen komen in groten getale naar de gebieden met doornen in de hele Barrens <snuift>, want het zijn heilige plaatsen. Maar geen enkele is zo heilig als Razorfen. Het hele Razorfen is het lichaam van Agamaggan. <snuift> Maar de Downs zijn extra beschermd, want de ingang is gemaakt van zijn grote muil! <snuift> Die slikt iedereen die hem niet trouw is in één keer door. En hij spuugt hun lichamen uit als hij ze heeft fijngekauwd! <snuift>$B$BAgamaggan heeft zijn lichaam achtergelaten om ons te beschermen. En hij geeft ons van zijn geest, zodat wij hem kunnen beschermen. <snuift>",
  c = "Ah, je begrijpt het echt. <snuift> Mijn woorden waren niet aan dovemansoren gericht, $r. Mangletooth zit misschien in een kooi, maar geen kooi kan de kracht van Agamaggan tegenhouden! <snuift>$B$BDe aanraking van de scherf, het gevoel ervan... het is lang geleden, $r.$B$BWeet je hoe het is? Om van je kracht afgesneden te worden?$B$BMaar dat is een verhaal voor een andere keer. Ik heb je informatie beloofd. Ik heb je de kracht van Agamaggan beloofd. Mijn volk keerde Mangletooth de rug toe. Nu laat ik jou op hen los. <snuift>",
  g = { {"doornen", "thorns (doorn)"}, {"invloed", "influence, effect"}, {"gemengd", "mixed (mengen)"}, {"graven ... op", "dig up (opgraven)"}, {"geheimen", "secrets (geheim)"}, {"in groten getale", "in great numbers, flock"}, {"heilige", "holy (heilig)"}, {"ingang", "entrance"}, {"muil", "maw, jaws"}, {"trouw", "loyal"}, {"slikt ... door", "swallows (doorslikken)"}, {"fijngekauwd", "chewed up (fijnkauwen)"}, {"aan dovemansoren gericht", "lost on deaf ears"}, {"aanraking", "touch"}, {"afgesneden", "cut off, severed (afsnijden)"}, {"laat ... op hen los", "set loose upon them (loslaten op)"} },
},

[868] = { en = "Egg Hunt", tier = 2,
  t = "Eierjacht",
  d = "Hé, $N. Ik ben naar de Crossroads gestuurd om over het land te waken. Ik moet noteren wat er gebeurt, voor mijn meesters in Orgrimmar.$B$BEén ding dat ik bestudeer, zijn de insectachtige wezens in het zuiden, in de Field of Giants. We weten weinig over die wezens, dus ik ga er meer over ontdekken. Ze lijken intelligent te zijn, meer dan een gewoon dier.$B$BNeem deze graafklauw en verzamel wat eieren van de wezens uit hun heuvels. Maar wees voorzichtig: als ze gealarmeerd worden, vallen ze je aan.",
  o = "Breng 12 Silithid Eggs en de Digging Claw naar Korran in de Crossroads.",
  p = "Wees voorzichtig met de eieren die je vindt, $N. Als ze breken, heb ik er niks aan.",
  c = "Je maakt me blij, $N. De eieren en het gereedschap. Goed gedaan.$B$BEn als beloning...",
  g = { {"Eierjacht", "egg hunt"}, {"waken", "watch over, keep watch"}, {"noteren", "take note, write down"}, {"meesters", "masters (meester)"}, {"bestudeer", "study (bestuderen)"}, {"insectachtige", "insect-like"}, {"wezens", "creatures (wezen)"}, {"ontdekken", "discover"}, {"graafklauw", "digging claw"}, {"heuvels", "mounds, hills (heuvel)"}, {"gealarmeerd", "alerted (alarmeren)"}, {"heb ik er niks aan", "they're no good to me"}, {"gereedschap", "tool(s)"}, {"beloning", "reward"} },
},

