[843] = { en = "Gann's Reclamation", tier = 2,
  t = "Ganns terugwinning",
  d = "Alleen dwaal ik over deze wegen.$b$bDe dwergen van Bael Modan hebben geen respect voor mijn land. Vreselijke ontploffingen slaan diepe gaten in de grond, terwijl lawaaiige machines de heuvels openscheuren. Land dat ooit een thuis was voor mijn stam en voor ons zorgde, zit nu vol met dwergen die alles vernielen.$b$bWe hebben geprobeerd om het met overleg op te lossen, maar dat is mislukt. Nu is het tijd om vastberaden te handelen.$b$bVerdrijf de dwergen met geweld uit de opgraving van Bael Modan. En breng me het dagboek van hun leider, Prospector Khazgorm.",
  o = "Gann Stonespire wil dat je 15 Bael'dun Excavators en 5 Bael'dun Foremen doodt.$b$bBreng Khazgorm's Journal naar Gann Stonespire.",
  p = "Veel onschuldige tauren zijn gestorven of werden van de geboortegrond van hun voorouders verjaagd, toen de dwergen van Bael Modan kwamen. Mijn land moet teruggewonnen worden!",
  c = "Khazgorm kreeg het lot dat hij verdiende. Ik voel geen spijt voor die dwaas. Hij was een ongelovige op deze landen.$b$bMoge zijn dood een waarschuwing zijn voor iedereen die onze manier van leven wil verstoren.$b$bLaat me nu even het dagboek van de dwerg bestuderen...",
  g = { {"terugwinning", "reclamation"}, {"dwaal", "wander (dwalen)"}, {"ontploffingen", "explosions, blasts (ontploffing)"}, {"lawaaiige", "noisy (lawaaiig)"}, {"openscheuren", "rip open"}, {"vernielen", "destroy, wreck"}, {"overleg", "negotiation, consultation"}, {"mislukt", "failed (mislukken)"}, {"vastberaden", "decisive(ly), determined"}, {"Verdrijf", "drive out (verdrijven)"}, {"opgraving", "excavation"}, {"dagboek", "journal, diary"}, {"onschuldige", "innocent (onschuldig)"}, {"geboortegrond", "birthplace, native land"}, {"voorouders", "ancestors (voorouder)"}, {"verjaagd", "chased away (verjagen)"}, {"lot", "fate"}, {"spijt", "remorse, regret"}, {"ongelovige", "infidel, unbeliever"}, {"verstoren", "disrupt, disturb"} },
},

[822] = { en = "Chen's Empty Keg", tier = 2,
  t = "Chens lege vat",
  d = "Lekker spul, die stormstout, hè?$B$BIk heb nog een recept dat ik van Chen heb geleerd. Heb je interesse? Het is snel gemaakt, en het kan handig zijn als je nog meer avonturen wilt beleven.$B$BBreng me 5 bliksemklieren van stormhides, 1 speekselklier van een greater thunderhawk, en een kodolever van een kodo uit de Barrens.$B$BZoals ik al zei: dit spul is sterk. Het is het trogg-bier waar ik je eerder over vertelde.",
  o = "Breng 5 Lightning Glands, 1 Thunderhawk Saliva Gland en 1 Kodo Liver naar Brewmaster Drohn in Ratchet.",
  p = "Werk je hard aan het vinden van die ingrediënten, $N?",
  c = "Haha! Ik wist dat je dit bier niet kon weerstaan. Kom altijd terug als je meer wilt, $N. Breng me dan gewoon meer van de ingrediënten die je voor me hebt verzameld.",
  g = { {"vat", "keg, barrel"}, {"spul", "stuff"}, {"recept", "recipe"}, {"handig", "useful, handy"}, {"avonturen", "adventures (avontuur)"}, {"beleven", "experience"}, {"bliksemklieren", "lightning glands (bliksemklier)"}, {"speekselklier", "saliva gland"}, {"kodolever", "kodo liver"}, {"ingrediënten", "ingredients (ingrediënt)"}, {"weerstaan", "resist"} },
},

