[893] = { en = "Weapons of Choice", tier = 2,
  t = "Wapens naar keuze",
  d = "Ik hoor dat de Razormane-quilboars in het zuiden, voorbij de Field of Giants, geen goede smeden hebben. Toch zijn ze blijkbaar begonnen met het maken van stevigere wapens. Ik wil graag een paar verschillende soorten in handen krijgen om hun technieken te leren, als dat kan.$B$BWil je eer brengen aan de Horde? Breng me dan voorbeelden van hun wapens. Zoek een dolk van hun stalkers, een toverstaf van hun zieners, en een schild van hun warfrenzy. Dan ben ik tevreden!",
  o = "Breng een Razormane Backstabber, een Charred Razormane Wand en een Razormane War Shield naar Tatternack Steelforge in Camp Taurajo in de Barrens.",
  p = "Ik twijfel er ook aan dat die zielige quilboars goed kunnen smeden. Maar ik doe wat de Warchief beveelt, en ik ga zoveel mogelijk leren over de Razormane-stam.$B$BIk heb wel saaiere taken gehad, en die doe ik graag als het de orcs helpt.",
  c = "Uitstekend, uitstekende exemplaren.$B$BDe quilboars zijn verder dan ik had verwacht.$B$BHier, $c, neem dit en ga uit de weg. Ik moet deze wapens beter bekijken. Misschien hebben we onze vijand onderschat. En zo'n fout kunnen we ons niet veroorloven.",
  g = { {"naar keuze", "of choice"}, {"smeden", "blacksmiths (smid); to forge"}, {"blijkbaar", "apparently"}, {"stevigere", "sturdier (stevig)"}, {"technieken", "techniques (techniek)"}, {"eer", "honor"}, {"dolk", "dagger"}, {"toverstaf", "wand"}, {"zieners", "seers (ziener)"}, {"schild", "shield"}, {"twijfel", "doubt (twijfelen)"}, {"zielige", "pathetic (zielig)"}, {"beveelt", "commands (bevelen)"}, {"saaiere", "more menial, duller (saai)"}, {"exemplaren", "specimens (exemplaar)"}, {"onderschat", "underestimated (onderschatten)"}, {"ons ... veroorloven", "afford (zich veroorloven)"} },
},

[897] = { en = "The Harvester", tier = 2,
  t = "De Harvester",
  d = "Dit vreemde, insectachtige wezen lijkt buiten de natuurlijke orde te staan. Het lijkt alsof het niet in de Barrens thuishoort.",
  o = "Breng de Harvester's Head naar Jorn Skyseer.",
  p = "Je lijkt bezorgd, $N. Hoe gaan je lessen in de Barrens? Heb je iets gevonden dat je verontrust?",
  c = "Ik kan niets zeggen over de aard van dit beest, want zijn geest is gevlucht. Maar zoals je al dacht: het hoort niet in de Barrens thuis. Ik vrees dat het een sombere toekomst voor ons volk aankondigt...$B$BMaar bereid je nu voor, en laten we hopen dat de tijd het mysterie van dit wezen oplost.",
  g = { {"natuurlijke", "natural (natuurlijk)"}, {"orde", "order"}, {"thuishoort", "belongs (thuishoren)"}, {"bezorgd", "worried, troubled"}, {"verontrust", "disturbs (verontrusten)"}, {"aard", "nature"}, {"gevlucht", "fled (vluchten)"}, {"vrees", "fear (vrezen)"}, {"sombere", "grim, gloomy (somber)"}, {"aankondigt", "heralds, announces (aankondigen)"}, {"bereid je ... voor", "prepare yourself (zich voorbereiden)"}, {"mysterie", "mystery"}, {"oplost", "solves, unravels (oplossen)"} },
},

[879] = { en = "Betrayal from Within", tier = 2,
  t = "Verraad van binnenuit",
  d = "Drie leden van mijn stam kwamen uit de Kraul om de aanvallen op de Horde te leiden, $r. <snuift> Ze zijn meedogenloos en sluw. Als je ze verslaat, krijgen je Crossroads en zelfs het grootste deel van de Barrens vrede... <snuift> tenminste van de Razormane-stam. <snuift>$B$BNak, Kuz en Lok Orcbane zijn degenen die je zoekt. Ze zijn ver in het zuiden van de Barrens. Eén is een spreukenwever, een ander een spoorzoeker, en hun leider, die Orcbane heet, <snuift> is een krijger. Dood ze, $r, zoals zij mij hebben gedood.",
  o = "Dood Nak, Kuz en Lok Orcbane en breng hun schedels naar Mangletooth in Camp Taurajo in de Barrens.",
  p = "Hoe gaat je jacht, $r? <snuift>$B$BThork denkt dat hij weet wie de aanvallen op zijn volk leidt, <snuift> maar hij zal leren hoe fout hij zit als het je lukt.$B$BMijn dood is onvermijdelijk. Maar jij hebt mijn vijanden veel pijn gedaan, dus Mangletooth heeft nergens spijt van. <snuift>",
  c = "Het is dus gedaan. Beter dat het zo eindigt, zegt Mangletooth. <snuift> Ze hadden <snuift> moeten zorgen dat ik dood was toen ze me de rug toekeerden. Nu lieten ze <snuift> me achter in deze vergeten kooi.$B$BEr is nog maar één taak voor je over, $r.",
  g = { {"Verraad", "betrayal"}, {"van binnenuit", "from within"}, {"leden", "members (lid)"}, {"aanvallen", "raids, attacks (aanval)"}, {"meedogenloos", "ruthless"}, {"sluw", "cunning"}, {"tenminste", "at least"}, {"degenen", "the ones"}, {"spreukenwever", "spell caster"}, {"spoorzoeker", "tracker"}, {"schedels", "skulls (schedel)"}, {"fout zit", "is wrong (fout zitten)"}, {"onvermijdelijk", "inescapable, unavoidable"}, {"vergeten", "forsaken, forgotten"} },
},

[885] = { en = "Washte Pawne", tier = 2,
  t = "Washte Pawne",
  d = "De veer van Washte Pawne doet pijn als je hem aanraakt.",
  o = "Breng Washte Pawne's Feather naar Jorn Skyseer in Camp Taurajo.",
  p = "Er zit nieuwe vastberadenheid in je, $N. Vastberadenheid die uit pijn geboren is...$B$BDraag je de last van de dood van Washte Pawne?",
  c = "De donderhavik is een zeldzaam beest in de Barrens. Zijn dood kan groot geluk voorspellen, of grote ondergang.$B$BMaar Washte Pawne, in het Taurahe \"Geestbijter\" genoemd, kan geen van beide brengen... of allebei.$B$BDe pijn die je voelde toen je op Geestbijter jaagde, is de steek die iedereen voelt die veel wint tegen een hoge prijs. De steek die je voelde, is de pijn van spijt.$B$BMaar ik zie dat je die hebt overwonnen. Je hebt geleerd dat spijt verandert in wijsheid, en dat je door pijn kracht krijgt.$B$BJe hebt veel geleerd, $N.",
  g = { {"veer", "feather"}, {"vastberadenheid", "resolve, determination"}, {"last", "burden"}, {"donderhavik", "thunderhawk"}, {"zeldzaam", "rare"}, {"voorspellen", "predict, portend"}, {"ondergang", "doom, downfall"}, {"Geestbijter", "Spirit Biter"}, {"geen van beide", "neither"}, {"steek", "sting, pang"}, {"prijs", "price, cost"}, {"overwonnen", "conquered, overcome (overwinnen)"} },
},

[906] = { en = "Betrayal from Within", tier = 2,
  t = "Verraad van binnenuit",
  d = "Breng het hoofd van Lok naar Thork in de Crossroads, $r. <snuift> Dan weet hij zonder woorden wat er met mijn stam is gebeurd. Ha, niet dat hij zou geloven dat Mangletooth <snuift> zulke dingen heeft helpen doen. Maar ik weet zeker dat hij je beloont voor zo'n grote daad. <snuift>$B$BIk blijf je zegenen met de kracht van Agamaggan zolang ik in deze kooi zit, $r. Tot dan, vaarwel.",
  o = "Breng Lok's Skull naar Thork in de Crossroads in de Barrens.",
  p = "Ja, wat is er?",
  c = "Heb je de leider van de Razormane gevonden en hem zelf gedood, $N? Geweldig.$B$BIk heb geen woorden, maar dat betekent niet dat ik je niet dankbaar ben. De mensen van de Crossroads doen er goed aan om je kracht te respecteren.$B$BIk moet toegeven: ik dacht dat de leider van deze aanvallen op onze aanvoerroutes een andere quilboar was. Nogmaals bedankt, $N.",
  g = { {"beloont", "rewards (belonen)"}, {"daad", "deed"}, {"zolang", "as long as"}, {"vaarwel", "farewell"}, {"dankbaar", "grateful"}, {"doen er goed aan", "would do well to (er goed aan doen)"}, {"toegeven", "admit"}, {"aanvoerroutes", "supply lines (aanvoerroute)"}, {"Nogmaals", "once again"} },
},

[3369] = { en = "In Nightmares", tier = 2,
  t = "In nachtmerries",
  d = "Deze scherf bevat grote geheimen. Hij is de pure essentie van de Emerald Dream. Maar wat ik in deze scherf zie, is geen droom. Zo'n visioen zou je een nachtmerrie noemen.$B$BIk wil je niet ongerust maken, $N, maar ik denk dat je deze scherf zo snel mogelijk aan een wijze druïde moet geven.$B$BJe moet Hamuul Runetotem op Elder Rise vinden. Ga naar Thunder Bluff. Meer kan ik niet zeggen.",
  o = "Breng de Nightmare Shard naar Hamuul Runetotem op Elder Rise.",
  p = "Kan ik je ergens mee helpen?",
  c = "Heeft Falla je naar mij gestuurd? Nou, laat me die scherf eens zien waar ze volgens jou zo aarzelend over sprak...$B$B<Hamuul kijkt in de scherf>$B$BOh... Ik had niet... Nou.$B$B$N, dank je dat je dit bij me hebt gebracht. Maar het is niet verstandig om over zulke dingen te praten, dat raad ik je aan. Hier moet je je niet mee bezighouden.$B$BLaten we zeggen dat de dingen in de Emerald Dream niet zo zijn als we dachten...$B$BMisschien kruisen onze wegen elkaar later nog eens.$b",
  g = { {"nachtmerries", "nightmares (nachtmerrie)"}, {"bevat", "contains (bevatten)"}, {"essentie", "essence"}, {"visioen", "vision"}, {"ongerust maken", "alarm, worry"}, {"aarzelend", "hesitant(ly)"}, {"verstandig", "wise, sensible"}, {"raad ... aan", "advise (aanraden)"}, {"je ... bezighouden", "concern yourself (zich bezighouden)"}, {"kruisen", "cross"} },
},

[3513] = { en = "The Runed Scroll", tier = 2,
  t = "De rol met runen",
  d = "De officieel uitziende rol is strak omwikkeld met een zilverachtig lint. Je weet zeker dat iemand dit wil zien, maar wie?$B$BEr is een buitenpost bij de grens met Ashenvale in het noorden. Als de informatie op deze rol over de nachtelfen gaat, is dat de plek om hem naartoe te brengen.",
  o = "Breng de Runed Scroll naar de noordelijke wachttoren in de Barrens.",
  p = "Wat heb je daar?",
  c = "Nou, nou... Waar heb je dit gevonden?",
  g = { {"runen", "runes (rune)"}, {"officieel uitziende", "official-looking"}, {"rol", "scroll, roll"}, {"strak", "tightly"}, {"omwikkeld", "wrapped (omwikkelen)"}, {"zilverachtig", "silvery"}, {"lint", "ribbon"}, {"nachtelfen", "night elves (nachtelf)"}, {"wachttoren", "guard tower"} },
},

[846] = { en = "Revenge of Gann", tier = 2,
  t = "De wraak van Gann",
  d = "Het is duidelijk dat de prospector afhankelijk was van explosieven en die lawaaiige voertuigen om de grond open te scheuren. We kunnen verwachten dat er snel een nieuwe voorman komt.$b$bIk wil de dwergen met hun eigen middelen terugpakken. Volgens deze plannen kunnen we een springlading maken als we nitroglycerine mengen met houtpulp en natriumnitraat. De schutters, soldaten en officieren in de Keep hebben die spullen, weten we.$b$bVerzamel deze dingen en breng ze naar me. Ik maak een lading die de dwergen niet zullen vergeten!",
  o = "Gann Stonespire wil dat je hem 6 flesjes Nitroglycerin, 6 bundels Wood Pulp en 6 monsters Sodium Nitrate brengt.",
  p = "Ik zie dat je terug bent, $n.$b$bDe dood van Khazgorm kan het graven in het land van mijn voorouders wat vertragen. Maar het maakt zeker geen einde aan de vernieling.$b$bDe Keep in Bael Modan wordt een steeds grotere militaire dreiging. Hij is gebouwd om de opgraving te verdedigen, maar nu is hij ook klaar om aan te vallen.$b$bAls je de ingrediënten hebt waar ik om vroeg, kan ik een lading maken. Die zal de haastige dwergen laten nadenken over wat ze hier in de Barrens doen.",
  c = "Ik zie dat je erg ijverig bent, $c.$b$bWe hebben zeker binnenkort een passende verrassing voor die dwergen.",
  g = { {"afhankelijk", "dependent"}, {"explosieven", "explosives (explosief)"}, {"voertuigen", "vehicles (voertuig)"}, {"voorman", "foreman"}, {"met hun eigen middelen terugpakken", "give them a taste of their own medicine"}, {"springlading", "explosive charge"}, {"houtpulp", "wood pulp"}, {"natriumnitraat", "sodium nitrate"}, {"schutters", "riflemen (schutter)"}, {"flesjes", "vials (flesje)"}, {"bundels", "bundles (bundel)"}, {"monsters", "samples (monster)"}, {"vertragen", "delay, slow down"}, {"vernieling", "destruction"}, {"verdedigen", "defend"}, {"haastige", "hasty (haastig)"}, {"ijverig", "industrious, hard-working"}, {"passende", "fitting (passend)"} },
},

[849] = { en = "Revenge of Gann", tier = 2,
  t = "De wraak van Gann",
  d = "Met de plannen van Khazgorm moet het geen probleem zijn om een springlading te maken.$b$bAh, daar is hij.$b$bNu, $n, ik ga je een speciale taak toevertrouwen. Neem deze springstok en blaas er de vliegmachine in Bael Modan mee op.$b$bDe vliegmachine is niet alleen een belangrijk deel van de opgraving. Hij is ook een oorlogswapen. En nog belangrijker: hij is een symbool van macht en een belediging voor de herinnering aan mijn stam.$b$bMaak me trots door deze heldhaftige taak te volbrengen, dan word je beloond.",
  o = "Vernietig de vliegmachine in Bael Modan en ga terug naar Gann Stonespire.",
  p = "Als de vliegmachine van de dwergen vernietigd is, voel ik de zoete voldoening van wraak.",
  c = "Goed gedaan, $n! Moge je in Thunder Bluff geëerd worden als beschermer van de heilige landen van de tauren, en als held van de verloren stam.",
  o1 = "Bael Modan Flying Machine vernietigd",
  g = { {"toevertrouwen", "entrust"}, {"springstok", "explosive stick"}, {"blaas ... op", "blow up (opblazen)"}, {"vliegmachine", "flying machine"}, {"oorlogswapen", "weapon of war"}, {"macht", "power"}, {"belediging", "insult"}, {"herinnering", "memory"}, {"heldhaftige", "heroic (heldhaftig)"}, {"volbrengen", "complete, accomplish"}, {"voldoening", "satisfaction"}, {"geëerd", "honored, revered (eren)"}, {"beschermer", "defender, protector"} },
},

[873] = { en = "Isha Awak", tier = 2,
  t = "Isha Awak",
  d = "De grote Isha Awak is de heer van deze wateren. Groot is zijn kracht, en ernstig zijn trots. De mensen aan de kust zijn bang voor hem, want hij heeft er al veel van opgegeten.$B$BMaar ik ben niet bang voor hem. Ik ben dankbaar dat hij hier is. Hij is een waardige uitdaging en een eervolle prooi.$B$BAls je er klaar voor bent, zwem dan naar buiten en zoek Isha Awak, de Diepe Ondergang.$B$BZijn geest woont in zijn hart. Wie het hart hoort kloppen, kent zijn lot.",
  o = "Breng het Heart of Isha Awak naar Mahren Skyseer.",
  p = "Wees niet bang voor het water, $r.",
  c = "Je bent nu één met Isha Awak, $N. Zijn geest is met je. Hij loert in je ogen...$B$BOgen die op een dag zullen leren zien.",
  g = { {"heer", "lord"}, {"ernstig", "solemn, serious"}, {"kust", "coast"}, {"waardige", "worthy (waardig)"}, {"eervolle", "honorable (eervol)"}, {"prooi", "prey"}, {"Ondergang", "doom"}, {"kloppen", "beat (of a heart)"}, {"lot", "fate"}, {"loert", "lurks (loeren)"} },
},

[874] = { en = "Mahren Skyseer", tier = 2,
  t = "Mahren Skyseer",
  d = "Je hebt op de beesten van de Barrens gejaagd. Je geest is sterk. Maar een jager moet altijd voorbereid zijn. Een echte jager kan een prooi langs elk pad besluipen. Bergen en moerassen houden $ghem:haar; niet tegen.$B$BZelfs de zee niet.$B$BZoek mijn zus, Mahren. Ze jaagt op de grote waterbeesten langs de kust. Zij leert je hoe die dieren leven.$B$BMaar wees voorzichtig als je haar zoekt, want de kust van de Barrens is in handen van mensen.",
  o = "Praat met Mahren Skyseer.",
  c = "Heeft mijn broer je gestuurd? Dan heb je jezelf aan hem bewezen. Als je het respect van Jorn hebt verdiend, heb je ook mijn respect.$B$BBen je klaar om verder te gaan op het pad van de jager?",
  g = { {"voorbereid", "prepared (voorbereiden)"}, {"besluipen", "stalk, sneak up on"}, {"moerassen", "swamps (moeras)"}, {"houden ... tegen", "stop, hold back (tegenhouden)"}, {"waterbeesten", "water beasts (waterbeest)"}, {"in handen van", "in the hands of, held by"}, {"bewezen", "proven (bewijzen)"}, {"verdiend", "earned (verdienen)"} },
},

[1153] = { en = "A New Ore Sample", tier = 2,
  t = "Een nieuw ertsmonster",
  d = "$C, je hebt me eerder goed geholpen. De warchief is tot nu toe tevreden met wat ik heb bereikt. Hij vraagt me om met nieuwe vastberadenheid door te gaan. Mijn eer zegt dat ik je bij de warchief de erkenning moet geven die je verdient voor alles wat je gedaan hebt. Maar eerst vraag ik je opnieuw om hulp.$B$BOnlangs kwamen er reizigers uit het zuiden, uit een plek die Thousand Needles heet. Daar doodden ze een kobold met een ongewoon ertsmonster. Maar ze wilden het niet verkopen. Ik wil een monster van dat erts om het te onderzoeken.",
  o = "Vind een Unrefined Ore Sample op een Gravelsnout Digger of Surveyor en breng het naar Tatternack Steelforge in Camp Taurajo in de Barrens.",
  p = "Ik zag de reizigers weer: degenen die me geen monster van het erts wilden verkopen. Ik spuugde naar ze, omdat ze de warchief niet wilden helpen.$B$BMogen ze sterven in de strijd als lafaards, en niet als krijgers. Dat zou het recht moeten zijn van iedereen die zich bij de Horde aansluit.",
  c = "Een goed monster, $N. Echt een goed monster.$B$BNu het jou gelukt is, kunnen die reizigers niet meer opscheppen over het erts dat ze vonden.$B$BIk ga er meteen mee aan het werk. Als het sterk genoeg blijkt, stuur ik een wapen van dit materiaal naar de warchief om hem ons succes te laten zien.$B$BIk zal je hulp niet vergeten, $C.",
  g = { {"ertsmonster", "ore sample"}, {"bereikt", "achieved (bereiken)"}, {"erkenning", "recognition"}, {"Onlangs", "recently"}, {"reizigers", "travelers (reiziger)"}, {"ongewoon", "unusual"}, {"onderzoeken", "examine, investigate"}, {"spuugde", "spat (spugen)"}, {"lafaards", "cowards (lafaard)"}, {"recht", "right"}, {"zich ... aansluit", "allies with, joins (zich aansluiten)"}, {"opscheppen", "boast, lord over"}, {"blijkt", "turns out, proves (blijken)"} },
},

[3514] = { en = "Horde Presence", tier = 2,
  t = "De aanwezigheid van de Horde",
  d = "Deze rol komt van die sluwe dryade Rynthariel, Keymaster van de Talon Den op Stonetalon Peak.$B$BZe zal geen contact meer hebben met de boodschapper van wie je dit hebt afgepakt, heh. Maar we moeten hier standhouden. De Horde accepteert haar lopers hier niet.$B$B$N, reis naar de Talon Den. Dood Rynthariel, en zet dan een teken neer dat iedereen kan zien. Neem deze Horde-vlag, $N. Zet hem neer in de Talon Den. Dan zijn ze niet meer zo dom om nog een boodschapper door ons gebied te sturen.",
  o = "Dood de leider van de Talon Den, Rynthariel the Keymaster.",
  p = "We kunnen de Alliance niet op ons land toestaan, $N. Laat dat duidelijk zijn.",
  c = "Jij bent een taaie! Rynthariel uit de Den verwijderen is een grote stap, $N. Het duurt lang voor ze zich weer verzamelen, dus we kunnen rekenen op minder Alliance-lopers in de Barrens. Ze denken wel twee keer na voordat ze er nog een deze kant op sturen.$B$BDank je.",
  g = { {"aanwezigheid", "presence"}, {"sluwe", "scheming, sly (sluw)"}, {"dryade", "dryad"}, {"boodschapper", "messenger"}, {"afgepakt", "taken from, looted (afpakken)"}, {"standhouden", "stand one's ground"}, {"lopers", "runners (loper)"}, {"vlag", "flag"}, {"gebied", "territory, area"}, {"toestaan", "allow"}, {"taaie", "tough one"}, {"verwijderen", "remove, rid"}, {"twee keer nadenken", "think twice"} },
},

})

